import cv2,numpy as np
T=cv2.imread('/app/target.png',0)<128;P=cv2.imread('/app/output/candidate_mask.png',0)>127
for n,(x0,y0,x1,y1) in enumerate([(300,650,375,780),(365,630,430,730),(425,615,485,710),(480,610,550,700)],1):
 t=T[y0:y1,x0:x1];p=P[y0:y1,x0:x1]
 def cen(a):
  yy,xx=np.where(a);return (xx.mean()+x0, yy.mean()+y0)
 best=(0,0,0)
 for dy in range(-15,16):
  for dx in range(-15,16):
   q=np.zeros_like(p);q[max(0,dy):min(p.shape[0],p.shape[0]+dy),max(0,dx):min(p.shape[1],p.shape[1]+dx)] = p[max(0,-dy):min(p.shape[0],p.shape[0]-dy),max(0,-dx):min(p.shape[1],p.shape[1]-dx)]
   i=(q&t).sum();u=(q|t).sum();s=i/u
   if s>best[0]:best=(s,dx,dy)
 print(n,'area t/p',t.sum(),p.sum(),'rec',np.logical_and(t,p).sum()/t.sum(),'centers',cen(t),cen(p),'best',best)
